const draft = $input.first().json;
const src = $('Build Generation Context').first().json;

const validation = {
  has_title: !!draft.title,
  has_sections: Array.isArray(draft.sections) && draft.sections.length >= 3,
  has_cta: !!draft.cta_copy,
  word_count: (draft.title || '') + JSON.stringify(draft.sections || []).replace(/[\u0000-\u007F]/g, ' ').split(/\s+/).length,
  contains_keyword: (draft.title || '').toLowerCase().includes((src.primary_keyword || '').toLowerCase())
};

const pass = validation.has_title && validation.has_sections && validation.has_cta && validation.word_count >= 300;

return [{ json: { ...src, draft, validation, valid: pass } }];

const src = $('Build Generation Context').first().json;
const system = 'أنت خبير SEO. أعد JSON صالحاً فقط.';
const content = JSON.stringify($('Validate Draft (Schema)').first().json.draft || {});
const user = 'نص المحتوى: ' + content +
  '\nالكلمة الرئيسية: ' + src.primary_keyword +
  '\nالكلمات الداعمة: ' + JSON.stringify(src.secondary_keywords) +
  '\nأعد: {"seo_title":"...","meta_description":"...","slug":"...","h1":"...","h2":["..."],"h3":["..."],"faq":[{"question":"...","answer":"..."}],"internal_links":["..."],"external_links":["..."],"image_alt":["..."],"schema_type":"Article","seo_score":0}." ;

return [{ json: { task_type: 'seo_optimizer', payload: { system, user } } }];

const seo = $input.first().json;
const src = $('Build Generation Context').first().json;

// SEO Score: مزج AI مع فحوص برمجية
const aiScore = Number(seo.seo_score) || 0;
const titleLen = (seo.seo_title || '').length;
const metaLen = (seo.meta_description || '').length;
const hasKeyword = (seo.seo_title || '').toLowerCase().includes((src.primary_keyword || '').toLowerCase());
const hasSlug = !!seo.slug && seo.slug.length >= 3;

const checks = {
  title_ok: titleLen >= 20 && titleLen <= 65,
  meta_ok: metaLen >= 50 && metaLen <= 160,
  keyword_in_title: hasKeyword,
  slug_ok: hasSlug,
  faq_present: Array.isArray(seo.faq) && seo.faq.length >= 1
};
const checkPass = Object.values(checks).filter(Boolean).length;
const computed = Math.round(aiScore * 0.7 + (checkPass / 4) * 100 * 0.3);

return [{ json: { ...src, seo, seo_score: computed, seo_checks: checks } }];

const src = $('Build Generation Context').first().json;
const draft = $('Validate Draft (Schema)').first().json.draft;
const system = 'أنت مدقق جودة محتوى صارم. أعد JSON صالحاً فقط.';
const user = 'نص المحتوى: ' + JSON.stringify(draft) +
  '\nالكلمة الرئيسية: ' + src.primary_keyword +
  '\nأعد: {"quality_scores":{"grammar":0,"readability":0,"seo":0,"accuracy":0,"relevance":0,"originality":0,"brand_compliance":0,"structure":0,"cta_clarity":0},"issues":[{"severity":"critical|warning","text":"...","fix":"..."}],"overall_score":0}. ';

return [{ json: { task_type: 'quality_reviewer', payload: { system, user } } }];

const qc = $input.first().json;
const s = qc.quality_scores || {};

const overall = Math.round(
  0.25*(s.grammar||0) + 0.20*(s.seo||0) + 0.15*(s.readability||0) +
  0.15*(s.brand_compliance||0) + 0.10*(s.originality||0) + 0.10*(s.structure||0) +
  0.05*(s.cta_clarity||0)
);
const criticalIssues = (qc.issues || []).filter(i => i.severity === 'critical').length;
const pass = overall >= ($env.QUALITY_THRESHOLD || 70) && criticalIssues === 0;

return [{ json: { ...$('Compute SEO Score (Code)').first().json, quality: qc, overall_score: overall, critical_issues: criticalIssues, quality_pass: pass } }];

const src = $('Build Generation Context').first().json;
const revision = src.revision_count + 1;
const maxRev = parseInt($env.MAX_REVISIONS || '2', 10);

if (revision > maxRev) {
  return [{ json: { ...$('Compute Quality Score (Code)').first().json, status: 'escalate', reason: 'max_revisions_exceeded' } }];
}

const draft = $('Validate Draft (Schema)').first().json.draft;
const issues = $('AI Quality Check').first().json.issues || $('Compute SEO Score (Code)').first().json.seo_checks;
const system = 'أنت محرر محتوى. أعد كتابة النص معالِجاً الملاحظات فقط. أعد JSON صالحاً.';
const user = 'الملاحظات: ' + JSON.stringify(issues) + '\nالنسخة: ' + JSON.stringify(draft);

return [{ json: { task_type: 'revision_agent', payload: { system, user }, revision_count: revision } }];
